const botOutput = $input.all()[0].json.output || '';
const token = $node['When chat message received'].json.token || $node['When chat message received'].json.body?.token || '';

// Parse save tags: [[SAVE:field:value]] or [[SAVE:field:value:extra]] (case-insensitive)
const saveMatches = [...botOutput.matchAll(/\[\[SAVE:([a-zA-Z_]+):([^:\]]+)(?::([^\]]+))?\]\]/gi)];
let patientData = {};

for (const m of saveMatches) {
    const field = m[1].toLowerCase();
    const val = m[2].trim();
    const extra = (m[3] || '').trim();

    if (field === 'gender') patientData.gender = val;
    else if (field === 'date_of_birth') patientData.date_of_birth = val;
    else if (field === 'is_smoker') patientData.is_smoker = val;
    else if (field === 'handedness') patientData.handedness = val;
    else if (field === 'weight') patientData.weight = val;
    else if (field === 'height') patientData.height = val;
    else if (field === 'blood_type') patientData.blood_type = val;
    else if (field === 'emergency_contact_name') patientData.emergency_contact_name = val;
    else if (field === 'emergency_contact_phone') patientData.emergency_contact_phone = val;
    else if (field === 'family_history') {
        if (!patientData.family_history) patientData.family_history = [];
        patientData.family_history.push({disease: val, relation: extra || 'Family'});
    } else if (field === 'allergies') {
        if (!patientData.allergies) patientData.allergies = [];
        patientData.allergies.push({allergy_name: val, severity: extra || 'Unknown'});
    } else if (field === 'current_medications') {
        if (!patientData.current_medications) patientData.current_medications = [];
        patientData.current_medications.push({medication_name: val, dosage: extra || 'Unknown'});
    } else if (field === 'chronic_diseases') {
        if (!patientData.chronic_diseases) patientData.chronic_diseases = [];
        patientData.chronic_diseases.push({disease_name: val, diagnosis_date: extra || null});
    } else if (field === 'surgeries') {
        if (!patientData.surgeries) patientData.surgeries = [];
        patientData.surgeries.push({surgery_name: val, date: extra || ''});
    }
}

// Parse urgency: [[ACTION:URGENT:Specialization]] (case-insensitive)
const urgentMatch = botOutput.match(/\[\[ACTION:(?:URGENT|FIND_DOCTOR):([^\]]+)\]\]/i);
let specialization = '';
if (urgentMatch) specialization = urgentMatch[1].trim();

// Clean output - remove all tags
let cleanOutput = botOutput
    .replace(/\[\[SAVE:[^\]]*\]\]/gi, '')
    .replace(/\[\[ACTION:[^\]]*\]\]/gi, '')
    .trim();

return [{
    json: {
        output: cleanOutput,
        patient_data: patientData,
        has_save: Object.keys(patientData).length > 0,
        specialization: specialization,
        token: token
    }
}];

const originalOutput = $node['Parse and Route'].json.output || '';
const doctorsData = $input.all()[0].json.doctors || [];
const hasDoctorRequest = $node['Parse and Route'].json.specialization !== '';
let finalOutput = originalOutput;

if (hasDoctorRequest && doctorsData && doctorsData.length > 0) {
    finalOutput += '\n\n🏥 Recommended Doctors:\n';
    for (let i = 0; i < Math.min(3, doctorsData.length); i++) {
        const doc = doctorsData[i];
        finalOutput += `• ${doc.name} — ${doc.specialization}`;
        if (doc.street) finalOutput += ` (${doc.street})`;
        finalOutput += '\n';
    }
}

return [{
    json: {
        output: finalOutput
    }
}];
